await harness.goToScene('FROST LAB');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(3);
await harness.stepFrames(30);
async function click(x, y) {
  harness.setMousePosition(x, y, 'UI');
  await harness.stepFrames(2);
  harness.setMouseButtonPressed(true);
  await harness.stepFrames(2);
  harness.setMouseButtonPressed(false);
  await harness.stepFrames(3);
}
async function holdRescue() {
  harness.setMousePosition(1190, 412, 'UI');
  await harness.stepFrames(2);
  harness.setMouseButtonPressed(true);
  await harness.stepFrames(2);
  if (harness.getSceneVariable('RescueHoldActive')?.value === true) {
    harness.setSceneVariable('RescueHoldTime', 1.195);
    await harness.stepFrames(6);
  }
  harness.setMouseButtonPressed(false);
  await harness.stepFrames(3);
}
async function tpPlayer(x, y) {
  const p = harness.getObjects('Player')[0];
  harness.setObjectPosition(p.id, x, y);
  await harness.stepFrames(5);
}
const actors = () => harness.getObjects('Actor');
const pvar = (n) => harness.getObjectVariable('Player', n)?.value;
const avar = (id, n) => harness.getObjectVariable(id, n)?.value;
// C1 C2: 7 participants, Player Wolf + 6 Human Actors
const pl = harness.getObjects('Player')[0];
harness.assert(actors().length === 6, `C1 6 actors + player, got ${actors().length}`);
harness.assert(pvar('Role') === 'Wolf' && pvar('State') === 'Active', `C2 player Wolf/Active`);
harness.assert(actors().every(a => avar(a.id,'Role')==='Human' && avar(a.id,'State')==='Active'), `C2 all actors Human/Active`);
// C3: same size
const a0 = actors()[0];
harness.assert(Math.abs(a0.width-pl.width)<0.1 && Math.abs((a0.depth??0)-(pl.depth??0))<0.1, `C3 same size w=${a0.width} d=${a0.depth}`);
// HUD initial (timer already ticking)
const ttxt = harness.getObjects('TimerText')[0];
harness.assert(ttxt.text === '3:30' || ttxt.text === '3:29', `K timer ticking, got ${ttxt.text}`);
harness.assert(harness.getObjects('RoleText')[0].text === 'あなた：人狼', `M role label`);
harness.assert(harness.getObjects('WolfButton')[0].hidden === false, `D WOLF button visible for wolf`);
// D: enter wolf mode via button
await click(1190, 332);
let wm = harness.getSceneVariable('WolfModeLeft')?.value ?? 0;
harness.assert(wm > 0, `D wolf mode entered (${wm})`);
// E: freeze first actor by contact
const t0 = actors()[0];
await tpPlayer(t0.centerX - 8.5, t0.centerY - 8.5);
await harness.stepFrames(10);
harness.assert(avar(t0.id,'State') === 'Frozen', `E actor frozen on contact`);
wm = harness.getSceneVariable('WolfModeLeft')?.value ?? -1;
harness.assert(wm > 0, `E wolf mode remains active after first freeze (${wm})`);
const t1 = actors()[1];
harness.assert(avar(t1.id,'State') === 'Active', `E second target remains Active without contact`);
harness.setSceneVariable('WolfModeLeft', 0);
harness.setSceneVariable('CooldownLeft', 0);
await harness.stepFrames(3);
// G: switch to human, rescue
await click(1190, 622);
harness.assert(pvar('Role') === 'Human', `N role toggled to Human`);
await tpPlayer(t0.centerX - 60, t0.centerY);
await harness.stepFrames(5);
harness.assert(harness.getObjects('RescueButton')[0].hidden === false, `G RESCUE shown near frozen`);
await click(1190, 412);
harness.assert(avar(t0.id,'State') === 'Frozen', `G a tap alone no longer thaws (hold required)`);
await holdRescue();
harness.assert(avar(t0.id,'State') === 'Active', `G frozen rescued to Active`);
// H: freeze again then infect (switch back to wolf first)
await click(1190, 622);
harness.setSceneVariable('CooldownLeft', 0);
await harness.stepFrames(3);
await click(1190, 332);
await tpPlayer(t0.centerX - 8.5, t0.centerY - 8.5);
await harness.stepFrames(10);
harness.assert(avar(t0.id,'State') === 'Frozen', `re-frozen for infect test`);
await tpPlayer(t0.centerX - 60, t0.centerY);
await harness.stepFrames(5);
harness.assert(harness.getObjects('InfectButton')[0].hidden === false, `H INFECT shown near frozen`);
await click(1190, 492);
harness.assert(avar(t0.id,'State') === 'FrozenWolfCandidate', `H infected to candidate`);
harness.assert(harness.getSceneVariable('InfectionUsed')?.value === true, `H infection used once`);
// I: trap — human rescues candidate
await click(1190, 622);
await tpPlayer(t0.centerX - 60, t0.centerY);
await harness.stepFrames(5);
await holdRescue();
harness.assert(pvar('State') === 'Frozen', `I rescuer becomes Frozen`);
harness.assert(avar(t0.id,'Role') === 'Wolf' && avar(t0.id,'State') === 'Active', `I candidate becomes Active Wolf`);
// N reset
await click(1190, 672);
await harness.stepFrames(5);
harness.assert(pvar('Role')==='Wolf' && pvar('State')==='Active', `N reset player`);
harness.assert(actors().every(a => avar(a.id,'Role')==='Human' && avar(a.id,'State')==='Active'), `N reset actors`);
harness.assert(harness.getSceneVariable('GameOver')?.value === false, `N reset gameover flag`);
// L wolf win: freeze 5 via setup, 1 via play
const list = actors();
for (let i = 0; i < 5; i++) harness.setObjectVariable(list[i].id, 'State', 'Frozen');
await harness.stepFrames(3);
harness.setSceneVariable('CooldownLeft', 0);
await harness.stepFrames(3);
await click(1190, 332);
const last = actors()[5];
await tpPlayer(last.centerX - 8.5, last.centerY - 8.5);
await harness.stepFrames(10);
harness.assert(harness.getSceneVariable('GameOver')?.value === true, `L game over on all frozen`);
harness.assert(harness.getObjects('WinText')[0].text === '人狼の勝利', `L 人狼の勝利 shown`);
// movement stopped after game over
const b4 = harness.getObjects('Player')[0];
harness.setKeyPressed('Right', true);
await harness.stepFrames(45);
harness.setKeyPressed('Right', false);
const af = harness.getObjects('Player')[0];
harness.assert(Math.hypot(af.centerX-b4.centerX, af.centerY-b4.centerY) < 5, `L frozen progression after win`);
// N reset then human win via timer
await click(1190, 672);
harness.setSceneVariable('MatchTimeLeft', 0.2);
await harness.stepFrames(20);
harness.assert(harness.getObjects('WinText')[0].text === '人間の勝利', `L 人間の勝利 on timeout`);

async function press(x, y) {
  harness.setMousePosition(x, y, 'UI');
  await harness.stepFrames(2);
  harness.setMouseButtonPressed(true);
  await harness.stepFrames(2);
}
async function release() {
  harness.setMouseButtonPressed(false);
  await harness.stepFrames(2);
}
const stateOf = (id) => harness.getObjectVariable(id, 'State')?.value;
const sceneNumber = (name) => harness.getSceneVariable(name)?.value ?? 0;
await harness.goToScene('FROST LAB');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(4);
harness.assert(sceneNumber('RescueHoldDuration') === 1.2, `hold duration is 1.2s: ${sceneNumber('RescueHoldDuration')}`);
const player = harness.getObjects('Player')[0];
harness.setObjectVariable(player.id, 'Role', 'Human');
const target = harness.getObjects('Actor')[0];
harness.setObjectPosition(player.id, 0, 350);
harness.setObjectPosition(target.id, 62, 350);
harness.setObjectVariable(target.id, 'State', 'Frozen');
await harness.stepFrames(3);
harness.assert(harness.getObjects('RescueButton')[0].hidden === false, 'rescue button is offered near a frozen neighbour');
// A short tap must not thaw: the gauge only fills while the finger is held.
await press(1190, 412);
await harness.stepFrames(3);
harness.assert(stateOf(target.id) === 'Frozen', 'a short tap never thaws');
harness.assert(sceneNumber('RescueHoldProgress') < 0.5, `tap fills only a sliver: ${sceneNumber('RescueHoldProgress')}`);
harness.assert(harness.getSceneVariable('RescueHoldActive')?.value === true, 'gauge is charging while pressed');
await release();
harness.assert(sceneNumber('RescueHoldTime') === 0, 'releasing resets the gauge');
harness.assert(harness.getSceneVariable('RescueHoldBarVisible')?.value === false, 'bar hides after release');
// Holding for the full 1.2s thaws the neighbour exactly once.
await press(1190, 412);
harness.setSceneVariable('RescueHoldTime', 1.195);
await harness.stepFrames(6);
harness.assert(stateOf(target.id) === 'Active', 'a full hold thaws the neighbour');
harness.assert(sceneNumber('RescueHoldCount') === 1, `one thaw counted: ${sceneNumber('RescueHoldCount')}`);
await harness.stepFrames(8);
harness.assert(stateOf(target.id) === 'Active', 'the same hold does not thaw twice');
harness.assert(sceneNumber('RescueHoldCount') === 1, 'the hold is spent until released');
await release();
// Walking away from the target resets the gauge instead of finishing it.
harness.setObjectVariable(target.id, 'State', 'Frozen');
await harness.stepFrames(2);
await press(1190, 412);
harness.setSceneVariable('RescueHoldTime', 1.0);
await harness.stepFrames(2);
harness.assert(harness.getSceneVariable('RescueHoldActive')?.value === true, 'gauge charges in range');
harness.setObjectPosition(player.id, 0, 180);
await harness.stepFrames(4);
harness.assert(sceneNumber('RescueHoldTime') === 0, 'leaving the target resets the gauge');
harness.assert(stateOf(target.id) === 'Frozen', 'no thaw happens after leaving the target');
await release();
harness.assert(harness.getSceneVariable('RescueHoldBarVisible')?.value === false, 'bar is hidden when idle');

const overlaps = (a, b) => (
  a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y
);
await harness.goToScene('FROST LAB');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(4);
const speedPads = harness.getObjects('SpeedPad');
const warpPads = harness.getObjects('WarpPad');
harness.assert(speedPads.length === 2, `two speed pads in the wide lanes: ${speedPads.length}`);
const inSideRoom = (pad) => (pad.centerX > -640 && pad.centerX < -320 && pad.centerY > -160 && pad.centerY < 160)
  || (pad.centerX > 320 && pad.centerX < 640 && pad.centerY > -160 && pad.centerY < 160);
for (const pad of speedPads) harness.assert(!inSideRoom(pad), `speed pad stays out of the side rooms: ${pad.centerX},${pad.centerY}`);
harness.assert(warpPads.length === 2, `one warp pair: ${warpPads.length}`);
const walls = harness.getObjects('Wall');
for (const pad of speedPads.concat(warpPads)) {
  for (const wall of walls) {
    harness.assert(!overlaps(pad, wall), `${pad.id === undefined ? 'pad' : pad.id} never overlaps a wall`);
  }
  harness.assert(pad.z >= 0, 'pad sits on the floor');
}
harness.assert(harness.getSceneVariable('SpeedFactor')?.value === 1, 'no boost before touching a pad');
const player = harness.getObjects('Player')[0];
const pad = speedPads[0];
harness.setObjectPosition(player.id, pad.centerX - 8.5, pad.centerY - 8.5);
await harness.stepFrames(3);
harness.assert((harness.getSceneVariable('SpeedBoostLeft')?.value ?? 0) > 2.0, `boost started: ${harness.getSceneVariable('SpeedBoostLeft')?.value}`);
harness.assert(Math.abs((harness.getSceneVariable('SpeedFactor')?.value ?? 1) - 1.45) < 0.01, 'speed factor is 1.45');
harness.assert(harness.getSceneVariable('SpeedPadTriggers')?.value === 1, 'one boost trigger');
harness.assert(harness.getObjects('ActionFeedbackText')[0].text.includes('スピードアップ'), `boost feedback: ${harness.getObjects('ActionFeedbackText')[0].text}`);
// boosted movement speed
const beforeBoost = harness.getObjects('Player')[0];
harness.setKeyPressed('Up', true);
await harness.stepFrames(18);
harness.setKeyPressed('Up', false);
const afterBoost = harness.getObjects('Player')[0];
const boosted = Math.abs(afterBoost.centerY - beforeBoost.centerY);
harness.setSceneVariable('SpeedBoostLeft', 0);
await harness.stepFrames(2);
harness.assert(harness.getSceneVariable('SpeedFactor')?.value === 1, 'boost expires back to normal speed');
const beforeNormal = harness.getObjects('Player')[0];
harness.setKeyPressed('Up', true);
await harness.stepFrames(18);
harness.setKeyPressed('Up', false);
const afterNormal = harness.getObjects('Player')[0];
const normal = Math.abs(afterNormal.centerY - beforeNormal.centerY);
harness.assert(normal > 10, `normal movement measured: ${normal}`);
const ratio = boosted / normal;
harness.assert(ratio > 1.3 && ratio < 1.62, `boosted movement is ~1.45x: ${ratio.toFixed(2)}`);
// warp pair
const from = warpPads[0];
const to = warpPads[1];
harness.setObjectPosition(player.id, from.centerX - 8.5, from.centerY - 8.5);
await harness.stepFrames(3);
harness.assert(harness.getSceneVariable('WarpCount')?.value === 1, `one warp: ${harness.getSceneVariable('WarpCount')?.value}`);
const afterWarp = harness.getObjects('Player')[0];
harness.assert(Math.hypot(afterWarp.centerX - to.centerX, afterWarp.centerY - to.centerY) < 30, 'player lands on the partner pad');
harness.assert((harness.getSceneVariable('WarpCooldownLeft')?.value ?? 0) > 4, 'five second cooldown starts');
harness.assert(harness.getObjects('ActionFeedbackText')[0].text.includes('ワープ'), 'warp feedback');
harness.setObjectPosition(player.id, to.centerX - 8.5, to.centerY - 8.5);
await harness.stepFrames(3);
harness.assert(harness.getSceneVariable('WarpCount')?.value === 1, 'the cooldown blocks a ping-pong warp');

const num = (name) => harness.getSceneVariable(name)?.value ?? -1;
await harness.goToScene('FROST LAB');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(8);
const player = harness.getObjects('Player')[0];
harness.assert(player.width === 17 && player.height === 17, `player hitbox stays 17x17: ${player.width}x${player.height}`);
harness.assert((player.depth ?? 0) === 32, `player depth stays 32: ${player.depth}`);
const actors = harness.getObjects('Actor');
harness.assert(actors.length === 6, `six actors: ${actors.length}`);
const mode = harness.getSceneVariable('CharacterRigMode')?.value;
harness.assert(['built', 'partial', 'unavailable'].includes(mode), `rig mode is reported: ${mode}`);
if (mode === 'built') {
  harness.assert(num('CharacterRigCount') === 7, `every character wears the rig: ${num('CharacterRigCount')}`);
  harness.assert(num('CharacterRigMeshes') === 42, `six parts per character: ${num('CharacterRigMeshes')}`);
  const firstMeshes = num('CharacterRigMeshes');
  await harness.stepFrames(40);
  harness.assert(num('CharacterRigMeshes') === firstMeshes, 'the rig is built once, never per frame');
  const frozenBefore = num('CharacterRigFrozen');
  harness.assert(frozenBefore === 0, `nobody is frozen at the start: ${frozenBefore}`);
  harness.setObjectVariable(actors[0].id, 'State', 'Frozen');
  await harness.stepFrames(3);
  harness.assert(num('CharacterRigFrozen') === 1, `the ice shell follows the frozen state: ${num('CharacterRigFrozen')}`);
  harness.setObjectVariable(actors[0].id, 'State', 'Active');
  await harness.stepFrames(3);
  harness.assert(num('CharacterRigFrozen') === 0, 'the ice shell clears when thawed');
  harness.assert(num('CharacterRigCount') === 7, 'the rig survives state changes');
}

const num = (name) => harness.getSceneVariable(name)?.value ?? -1;
const flag = (name) => harness.getSceneVariable(name)?.value === true;
async function press(x, y) {
  harness.setMousePosition(x, y, 'UI');
  await harness.stepFrames(2);
  harness.setMouseButtonPressed(true);
  await harness.stepFrames(2);
}
async function release() {
  harness.setMouseButtonPressed(false);
  await harness.stepFrames(3);
}
await harness.goToScene('FROST LAB');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(4);
harness.assert(num('RescueHoldMeterDiameter') === 68, `the thaw gauge is a 68px ring: ${num('RescueHoldMeterDiameter')}`);
const circumference = num('RescueHoldMeterCircumference');
harness.assert(circumference > 170 && circumference < 200, `the ring circumference follows its radius: ${circumference}`);
harness.assert(num('RescueHoldMeterDash') > 170, `the empty ring starts fully open: ${num('RescueHoldMeterDash')}`);
const mode = harness.getSceneVariable('RescueHoldMeterMode')?.value;
harness.assert(mode === 'ring', `the circular meter is active: ${mode}`);
const player = harness.getObjects('Player')[0];
harness.setObjectVariable(player.id, 'Role', 'Human');
const target = harness.getObjects('Actor')[0];
harness.setObjectPosition(player.id, 0, 350);
harness.setObjectPosition(target.id, 62, 350);
harness.setObjectVariable(target.id, 'State', 'Frozen');
await harness.stepFrames(3);
harness.assert(harness.getObjects('RescueButton')[0].hidden === false, 'the rescue button is offered near a frozen neighbour');
harness.assert(flag('RescueHoldMeterVisible') === false, 'the ring stays hidden until the hold starts');
await press(1190, 412);
harness.setSceneVariable('RescueHoldTime', 0.6);
await harness.stepFrames(2);
const half = num('RescueHoldMeterPercent');
harness.assert(half >= 45 && half <= 62, `the ring reads part way: ${half}%`);
const dash = num('RescueHoldMeterDash');
harness.assert(Math.abs(dash - circumference * (1 - half / 100)) < circumference * 0.03, `the arc follows the percentage: ${dash} of ${circumference} at ${half}%`);
harness.assert(flag('RescueHoldMeterVisible') === true, 'the ring is on screen while charging');
harness.assert(flag('RescueHoldReady') === false, 'half a ring is not a thaw yet');
harness.assert(harness.getObjectVariable(target.id, 'State')?.value === 'Frozen', 'half a ring never thaws');
harness.setSceneVariable('RescueHoldTime', 1.201);
await harness.stepFrames(1);
harness.assert(flag('RescueHoldReady') === true, 'a full ring is ready');
harness.assert(num('RescueHoldMeterPercent') === 100, `the full ring reads 100%: ${num('RescueHoldMeterPercent')}`);
harness.assert(num('RescueHoldMeterDash') === 0, `the full ring closes the arc: ${num('RescueHoldMeterDash')}`);
harness.assert(num('RescueHoldCount') === 1, `the thaw is counted once: ${num('RescueHoldCount')}`);
harness.assert(harness.getObjectVariable(target.id, 'State')?.value === 'Active', 'the full ring thaws the neighbour');
await release();
harness.assert(flag('RescueHoldMeterVisible') === false, 'the ring disappears after the hold');
harness.assert(num('RescueHoldMeterPercent') === 0, `the ring resets to empty: ${num('RescueHoldMeterPercent')}`);
harness.assert(Math.abs(num('RescueHoldMeterDash') - circumference) < 0.5, `the arc refills on reset: ${num('RescueHoldMeterDash')}`);
harness.assert(harness.getSceneVariable('RescueHoldMeterReady')?.value === true, 'the ring element survives the reset');

const num = (name) => harness.getSceneVariable(name)?.value ?? -1;
const str = (name) => harness.getSceneVariable(name)?.value ?? '';
const flag = (name) => harness.getSceneVariable(name)?.value === true;
await harness.goToScene('FROST LAB');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(4);
harness.assert(flag('SoundEngineReady') === true, 'the Web Audio observer is installed');
if (harness.getSceneVariable('SoundEnabled')?.value !== true) {
  harness.setSceneVariable('SoundToggleRequest', true);
  await harness.stepFrames(2);
}
harness.assert(flag('SoundEnabled') === true, `sound is enabled: ${flag('SoundEnabled')}`);
const toggles0 = num('SoundToggleCount');
harness.assert(str('SoundMode') !== '', `the sound engine reports its state: ${str('SoundMode')}`);
const baseCount = num('SoundPlayCount');
const actor = harness.getObjects('Actor')[0];
harness.setObjectVariable(actor.id, 'State', 'Frozen');
await harness.stepFrames(2);
harness.assert(str('SoundLast') === 'freeze', `freezing cues the ice sound: ${str('SoundLast')}`);
harness.assert(num('SoundPlayCount') === baseCount + 1, `one cue per freeze: ${num('SoundPlayCount') - baseCount}`);
harness.setObjectVariable(actor.id, 'State', 'Active');
await harness.stepFrames(2);
harness.assert(str('SoundLast') === 'thaw', `thawing cues the melt sound: ${str('SoundLast')}`);
harness.setSceneVariable('WarpCount', num('WarpCount') + 1);
await harness.stepFrames(2);
harness.assert(str('SoundLast') === 'warp', `warping cues the warp sound: ${str('SoundLast')}`);
harness.setSceneVariable('SpeedPadTriggers', num('SpeedPadTriggers') + 1);
await harness.stepFrames(2);
harness.assert(str('SoundLast') === 'speed', `a speed pad cues the boost sound: ${str('SoundLast')}`);
harness.setSceneVariable('RoundPhase', 'Countdown');
harness.setSceneVariable('RoundPhaseLeft', 3.0);
await harness.stepFrames(2);
harness.assert(str('SoundLast') === 'count', `the countdown ticks: ${str('SoundLast')}`);
harness.setSceneVariable('RoundPhaseLeft', 0.05);
await harness.stepFrames(2);
harness.assert(str('SoundLast') === 'start', `the start cue fires: ${str('SoundLast')}`);
harness.setSceneVariable('RoundPhase', 'Active');
await harness.stepFrames(2);
harness.setObjectVariable('Player', 'Role', 'Wolf');
harness.setObjectVariable('Player', 'State', 'Active');
for (const other of harness.getObjects('Actor')) {
  harness.setObjectVariable(other.id, 'Role', 'Human');
  harness.setObjectVariable(other.id, 'State', 'Frozen');
}
await harness.stepFrames(3);
harness.assert(harness.getSceneVariable('GameOver')?.value === true, 'the wolf win ends the round');
harness.assert(str('SoundLast') === 'win', `a win cues the fanfare: ${str('SoundLast')}`);
harness.setSceneVariable('RoundCommand', 'Restart');
await harness.stepFrames(4);
harness.assert(harness.getSceneVariable('GameOver')?.value === false, 'the restart resumes play');
harness.setObjectVariable('Player', 'Role', 'Wolf');
harness.setObjectVariable('Player', 'State', 'Active');
for (const other of harness.getObjects('Actor')) {
  harness.setObjectVariable(other.id, 'Role', 'Human');
  harness.setObjectVariable(other.id, 'State', 'Active');
}
await harness.stepFrames(2);
harness.setSceneVariable('MatchTimeLeft', 0.2);
await harness.stepFrames(20);
harness.assert(str('SoundLast') === 'lose', `a loss cues the defeat sound: ${str('SoundLast')}`);
harness.setSceneVariable('RoundCommand', 'Restart');
await harness.stepFrames(4);
const muted = num('SoundPlayCount');
harness.setSceneVariable('SoundToggleRequest', true);
await harness.stepFrames(2);
harness.assert(flag('SoundEnabled') === false, 'the SETTINGS toggle turns sound off');
harness.assert(num('SoundToggleCount') === toggles0 + 1, `one toggle recorded: ${num('SoundToggleCount')}`);
const victim = harness.getObjects('Actor')[1];
harness.setObjectVariable(victim.id, 'State', 'Frozen');
await harness.stepFrames(3);
harness.assert(num('SoundPlayCount') === muted, `muted means no cue is played: ${num('SoundPlayCount') - muted}`);
harness.setSceneVariable('SoundToggleRequest', true);
await harness.stepFrames(2);
harness.assert(flag('SoundEnabled') === true, 'the toggle turns sound back on');
const resumed = num('SoundPlayCount');
harness.setObjectVariable(victim.id, 'State', 'Active');
await harness.stepFrames(2);
harness.assert(num('SoundPlayCount') === resumed + 1, 'cues resume after unmuting');

const num = (name) => harness.getSceneVariable(name)?.value ?? -1;
await harness.goToScene('FROST LAB');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(4);
await harness.stepFrames(8);
harness.assert(num('ActorIdLabelFontSize') === 11, `the head labels shrink to the v0.6.10 11px plate: ${num('ActorIdLabelFontSize')}`);
harness.assert(num('ActorIdLabelLineHeight') === 13, `the plate line height is 13px: ${num('ActorIdLabelLineHeight')}`);
harness.assert(harness.getSceneVariable('ActorIdLabelsReady')?.value === true, 'the label overlay still initialises');
const player = harness.getObjects('Player')[0];
